			this._writeToStorage()
		}
	}
	async getAssignments(): Promise<PersistedAssignmentData | null> { return this._config._testAssignments }
	async storeAssignments(data: PersistedAssignmentData): Promise<void> {
		if (this._config._testAssignments !== data) {
			this._config._testAssignments = data
			this._writeToStorage()
		}
	}
}

/** Migrates older credential formats in place while retaining every other field. */
export function migrateConfig(loadedConfig: any) {
	if (Array.isArray(loadedConfig._credentials)) migrateConfigV2to3(loadedConfig)
	loadedConfig._version = DeviceConfig.Version
}

/** Exported for testing. */
export function migrateConfigV2to3(loadedConfig: any) {
	if (!Array.isArray(loadedConfig._credentials)) return
	const credentials: Record<string, PersistentCredentials> = {}
	for (const oldCredential of loadedConfig._credentials) {
		const userId = oldCredential.credentialInfo?.userId ?? oldCredential.userId
		const login = oldCredential.mailAddress ?? userId
		const type = oldCredential.credentialInfo?.type ?? (String(login).includes("@") ? "internal" : "external")
		credentials[userId] = {
			...oldCredential,
			credentialInfo: oldCredential.credentialInfo ?? {login, userId, type},
		}
		delete (credentials[userId] as any).mailAddress
		delete (credentials[userId] as any).userId
	}
	loadedConfig._credentials = credentials
	loadedConfig._version = DeviceConfig.Version
}

export const deviceConfig: DeviceConfig = new DeviceConfig(DeviceConfig.Version, availableStorage())
